package com.nigson.integration.carrier;

import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import com.nigson.integration.platform.*;
import com.nigson.integration.providers.CarrierProvider;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.*;
import tools.jackson.databind.JsonNode;

/** A staff command can schedule reads of existing evidence, never another carrier create. */
public final class CarrierReconciliationService {
 public record Request(UUID bookingRequestId,String mode,String reason){public Request{ApiValues.uuid(bookingRequestId==null?null:bookingRequestId.toString());if(!Set.of("MOCK","SANDBOX","LIVE").contains(Objects.requireNonNullElse(mode,""))||reason==null||reason.isBlank()||reason.length()<10||reason.length()>500||reason.codePoints().anyMatch(Character::isISOControl))throw ApiValues.invalid();}@Override public String toString(){return "CarrierReconciliationRequest[protected]";}}
 public record Result(UUID shipmentId,String state,UUID jobId){public Result{ApiValues.uuid(shipmentId==null?null:shipmentId.toString());ApiValues.uuid(jobId==null?null:jobId.toString());if(!Set.of("BOOKED","UNKNOWN","FAILED").contains(Objects.requireNonNullElse(state,"")))throw ApiValues.invalid();}}
 public static Request request(JsonNode body){if(body==null||!body.isObject()||!body.propertyNames().equals(Set.of("bookingRequestId","mode","reason")))throw ApiValues.invalid();for(var value:body)if(!value.isString())throw ApiValues.invalid();return new Request(ApiValues.uuid(body.path("bookingRequestId").asString()),body.path("mode").asString(),body.path("reason").asString());}
 private final JdbcTemplate jdbc;private final PlatformStore commands;private final AuditWriter audit;private final CarrierProvider provider;private final Clock clock;
 public CarrierReconciliationService(JdbcTemplate jdbc,PlatformStore commands,AuditWriter audit,CarrierProvider provider,Clock clock){this.jdbc=jdbc;this.commands=commands;this.audit=audit;this.provider=provider;this.clock=clock;}
 private void proof(PrivateWorkload.Proof proof){var route=PrivateWorkload.ROUTES.stream().filter(r->r.api().equals("API-196")).findFirst().orElseThrow(ActorAssertion::denied);if(proof==null||!route.equals(proof.route())||!route.client().equals(proof.client())||proof.subject()==null||!proof.subject().matches("[A-Za-z0-9._:-]{1,100}")||proof.actor()==null||proof.actor().organization()!=null||!proof.actor().roles().contains("OPERATIONS")||!proof.actor().scopes().contains(route.scope()))throw ActorAssertion.denied();ActorAssertion.recentMfa(proof.actor(),clock);}
 public Result reconcile(PrivateWorkload.Proof proof,UUID shipment,Request input,UUID command,UUID correlation){proof(proof);for(UUID id:Arrays.asList(shipment,command,correlation))ApiValues.uuid(id==null?null:id.toString());Objects.requireNonNull(input);String mode=provider.mode()==ProviderHttp.Mode.TEST?"SANDBOX":provider.mode().name();if(!mode.equals(input.mode()))throw new Problem.Failure(ProblemCode.PROVIDER_MODE_MISMATCH);String principal="nigson-commerce:carrier-reconcile:"+proof.actor().party();var request=EventCodec.JSON.valueToTree(Map.of("shipment",shipment,"input",input));var saved=commands.executeLocal(principal,"API-196",command.toString(),request,db->{
  proof(proof);jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");var books=jdbc.queryForList("SELECT * FROM integration.carrier_booking WHERE shipment_id=? AND provider='FEDEX' FOR UPDATE",shipment);if(books.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var b=books.getFirst();String business="carrier-booking:"+input.bookingRequestId();if(!business.equals(b.get("business_key")))throw new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);if(!mode.equals(b.get("mode")))throw new Problem.Failure(ProblemCode.PROVIDER_MODE_MISMATCH);var jobs=jdbc.queryForList("SELECT * FROM integration.integration_job WHERE business_key=? FOR UPDATE",business);if(jobs.size()!=1)throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);var j=jobs.getFirst();if(!"commerce".equals(j.get("owner_service"))||!"LOGISTICS_CREATE".equals(j.get("kind"))||!shipment.equals(j.get("resource_id")))throw CarrierValues.rule();var cursor=EventCodec.JSON.readTree(j.get("cursor").toString());if(!CarrierBookingExecution.checkpoint(cursor))throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);if(!provider.accountFingerprint().equals(cursor.path("accountHash").asString()))throw new Problem.Failure(ProblemCode.PROVIDER_MODE_MISMATCH);String expectedHash="INTENT".equals(cursor.path("stage").asString())?EventCodec.hash(EventCodec.JSON.valueToTree(Map.of("shipment_id",shipment.toString(),"booking_request_id",input.bookingRequestId().toString(),"provider","FEDEX"))):cursor.path("requestHash").asString();if(!expectedHash.equals(b.get("request_hash")))throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);if("CANCELLED".equals(b.get("state")))throw new Problem.Failure(ProblemCode.INVALID_TRANSITION);
  boolean booked="BOOKED".equals(b.get("state"));boolean active=false;for(var row:List.of(b,j)){var lease=(java.sql.Timestamp)row.get("lease_until");if(lease!=null&&lease.toInstant().isAfter(clock.instant()))active=true;}
  if(booked&&(!"COMPLETE".equals(cursor.path("stage").asString())||!"SUCCEEDED".equals(j.get("state")))||!booked&&"SUCCEEDED".equals(j.get("state")))throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);
  if(!active){if(booked){boolean terminal=Set.of("DELIVERED","CANCELLED").contains(cursor.path("tracking").path("last").path("status").asString());if(!terminal)jdbc.update("UPDATE integration.carrier_booking SET next_poll_at=?,version=version+1,updated_at=?,updated_by=? WHERE id=?",java.sql.Timestamp.from(clock.instant()),java.sql.Timestamp.from(clock.instant()),proof.actor().party().toString(),b.get("id"));}else{jdbc.update("UPDATE integration.carrier_booking SET state='UNKNOWN',lease_until=NULL,next_poll_at=?,error_code='PROVIDER_OUTCOME_UNKNOWN',version=version+1,updated_at=?,updated_by=? WHERE id=?",java.sql.Timestamp.from(clock.instant()),java.sql.Timestamp.from(clock.instant()),proof.actor().party().toString(),b.get("id"));jdbc.update("UPDATE integration.integration_job SET state='UNKNOWN',lease_until=NULL,next_attempt_at=?,error_code='PROVIDER_OUTCOME_UNKNOWN',version=version+1,updated_at=?,updated_by=? WHERE id=?",java.sql.Timestamp.from(clock.instant()),java.sql.Timestamp.from(clock.instant()),proof.actor().party().toString(),j.get("id"));}}
  audit.append(proof.actor().party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.QUEUE_REPLAY,AuditValues.Resource.QUEUE,(UUID)j.get("id"),correlation,AuditValues.Reason.OPERATOR_REQUEST,Map.of("state",j.get("state")),Map.of("state",booked?"SUCCEEDED":active?j.get("state"):"UNKNOWN"),null);var result=new Result(shipment,booked?"BOOKED":"UNKNOWN",(UUID)j.get("id"));return new PlatformStore.Response(202,EventCodec.JSON.valueToTree(result),shipment);
 });return EventCodec.JSON.treeToValue(saved.body(),Result.class);}
}
